import re
from .epc_section_generic import EpcSectionGeneric, EpcLine
from ..utils.logger import logger


class SectionSgw(EpcSectionGeneric):
    """
    Section "Sgw" is a part of epc.lua config file.
    Generated content base on epc.yaml.
    Example generated for CLOUD_R4A_CUS:

    exec("set_sgw id=1 ip=:10000 s1u=10.0.1.1:2152 s11=10.0.1.1:2153")
    """

    def _prepare_section_content(self, epc_config, *args, **kwargs):
        sgw_keys = filter(self._filter_sgw, sorted(epc_config.keys()))
        if not sgw_keys:
            return
        logger.debug("Generating SGW section")
        subsection = []
        for sgw in sgw_keys:
            sgw_num = re.match(r'sgw(?P<sgw_num>\d+)', sgw).group('sgw_num')
            s1u_addr = self.get_s11_or_s1u_addr(epc_config[sgw], 's1u_addr')
            s11_addr = self.get_s11_or_s1u_addr(epc_config[sgw], 's11_addr')

            sgw_line = f"set_sgw id={sgw_num} ip=:{self.EDAEMON_PORT} s1u={s1u_addr}:2152 s11={s11_addr}:2153"
            subsection.append(EpcLine(line=sgw_line, exec=True, tab_count=0))

        self._section_content.append(subsection)

    @staticmethod
    def get_s11_or_s1u_addr(sgw_data, s11_or_s1u_addr):
        mme_s1_addr = '10.254.221.1'  # TODO must chceck if needed
        if s11_or_s1u_addr in sgw_data and sgw_data[s11_or_s1u_addr] != 'default':
            mme_s1_addr = sgw_data[s11_or_s1u_addr]

        return mme_s1_addr

    @staticmethod
    def _filter_sgw(s):
        return re.match(r'sgw\d+', s) is not None
